fn replace(v: &mut Vec<i32>, x: i32, y: i32) {
    for elem in v.iter_mut() {
        if *elem == x {
            *elem = y;
        }
    }
}

fn main() {
    // Example usage:
    let mut data = vec![1, 2, 3, 2, 4];
    replace(&mut data, 2, 99);
    assert_eq!(data, vec![1, 99, 3, 99, 4]);
    println!("Replaced vector: {:?}", data);
}